sp_page.css:
section.page {
  background: radial-gradient(at right bottom, #f8f6f6 6.56%, #f8f6f6 11.16%, #f8f6f6 17.26%, #f8f6f6 22.64%, #f8f6f6 42.58%);
}

.icon-homepage-sphvs{
  background-color: rgba(237,241,242, 0.95);
  border-radius: 4px;
}

.css_home_dimension{
  width: 1600px; 
  height: 100%;
  margin: 0 auto;
  padding-top: 30px;
  float: left;
}

.header_background {
  background-image: url(e68c9c3….iix);
  height: 15vh;
  background-repeat: no-repeat;
  background-size: cover !important;
  align-content: center;
}

.icon_link {
  text-align: center;
}

body .padding-top {
  padding-top:0rem !important;
}
